window.AUTH=window.AUTH||{};window.AUTH["18-916"]={"d":"18-916","id":"2019/18-916","n":"Thryv, Inc. v. Click-To-Call Technologies, LP","briefs":[{"k":"respondent","label":"Brief of Federal Respondent supporting reversal","date":"2019-09-03","url":"https://www.supremecourt.gov/DocketPDF/18/18-916/114529/20190903181248356_18-916bsUnitedStates.pdf","side":"res","n":90},{"k":"petitioner","label":"Brief of petitioner Thryv, Inc., fka Dex Media, Inc.","date":"2019-09-03","url":"https://www.supremecourt.gov/DocketPDF/18/18-916/114413/20190903121952203_18-916%20Brief%20For%20Petitioner.pdf","side":"pet","n":86},{"k":"respondent","label":"Brief of respondent Click-To-Call Technologies, LP","date":"2019-10-28","url":"https://www.supremecourt.gov/DocketPDF/18/18-916/120560/20191028203601792_18-916bsClick-to-Call.pdf","side":"res","n":72},{"k":"reply","label":"Reply of petitioner Thryv, Inc., fka Dex Media, Inc.","date":"2019-11-26","url":"https://www.supremecourt.gov/DocketPDF/18/18-916/123708/20191126131635589_Reply%20Brief.pdf","side":"pet","n":47}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=61","tr":true,"items":[{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"25","2":"13"}},{"t":"case","label":"Achates Reference Publ’g, Inc. v. Apple Inc.","cite":"803 F.3d 652","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/803/652/","by":{"0":"8","1":"10"}},{"t":"case","label":"Applications in Internet Time, LLC v. RPX Corp.","cite":"897 F.3d 1336","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/897/1336/","by":{"0":"35","1":"38"}},{"t":"case","label":"(III) Cases—Continued: Belkin Int’l, Inc. v. Kappos","cite":"696 F.3d 1379","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/696/1379/","by":{"0":"23"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"op":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 25","1":"16","3":"2"}},{"t":"case","label":"Callaway Golf Co. v. Kappos","cite":"802 F. Supp. 2d 678","y":2011,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/802/678/","by":{"0":"23"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Dalton v. Specter","cite":"511 U.S. 462","y":1994,"id":"1993/93-289","sc":1,"ar":1,"sum":"Judicial review is not available for respondents' claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","2":"12, 27"}},{"t":"case","label":"Heinl v. Godici","cite":"143 F. Supp. 2d 593","y":2001,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/143/593/","sum":"Noting that Section 303(c) “explicitly addresses only a denial of a petition for reexamination, not the grant of such a petition”.","sumSrc":"brief:0","by":{"0":"21"}},{"t":"case","label":"Johnson v. Robison","cite":"415 U.S. 361","y":1974,"id":"1973/72-1297","sc":1,"sum":"Appellee, who had been exempted from military service as a Class 1-0 conscientious objector bo. who perfurmed required alternative civilian service, after being denied educational benefits under the Veterans' Readjustmcnt Benefits Act of 1966 brought this class action for a declaratory judgment that' the provisions of the Act making him and his class ineligible for such benefits violated the First Amendment's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 31"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"19","2":"passim"}},{"t":"case","label":"Lindahl v. OPM","cite":"470 U.S. 768","y":1985,"id":"1984/83-5954","sc":1,"sum":"The Office of Personnel Management (OPM) \"determine[s] questions of disability and dependency\" in administering the Federal Government's disability retirement program. 5 U. S. C. § 8347(c). Its \"decisions... concerning these matters are final and conclusive and are not subject to review,\" ibid., except to the extent that administrative review by the Merit Systems Protection Board (MSPB) is provided by §8347(d)(1). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"19"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"sum":"Explaining that the presumption “fails when a statute’s language or structure demonstrates that Congress wanted an agency to police its own conduct”.","sumSrc":"brief:0","by":{"0":"2, 20","2":"passim","3":"2, 15"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"5, 7, 10, 13, 19"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Synopsys, Inc. v. Matal","cite":"280 F. Supp. 3d 823","y":2017,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/280/823/","by":{"0":"21"}},{"t":"case","label":"Traynor v. Turnage","cite":"485 U.S. 535","y":1988,"id":"1987/86-622","sc":1,"sum":"Petitioners in these cases are honorably discharged veterans who did not exhaust their \"GI Bill\" educational assistance benefits within 10 years following their military service, as required by 38 U. S. C. § 1662(a)(1). Under that section, veterans may obtain an extension of the delimiting period if they were prevented from using their benefits earlier by \"a physical or mental disorder which was not the result of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 31"}},{"t":"case","label":"University of Texas S.W. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"sum":"The Court found that Title VII of the Civil Rights Act of 1964 requires the plaintiff to prove their employer would not have taken an action but for the existence of improper motives.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"WesternGeco LLC v. ION Geophysical Corp.","cite":"889 F.3d 1308","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/889/1308/","by":{"0":"35","1":"39"}},{"t":"case","label":"Case—Continued: Wi-Fi One, LLC v. Broadcom Corp.: 837 F.3d 1329 (Fed. Cir. 2016), vacated and remanded","cite":"878 F.3d 1364","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/878/1364/","op":4,"ar":1,"sum":"Stating that “Section 314(d)’s bar on appellate review is directed to the Director’s assessment of the substantive adequacy of a timely filed petition”.","sumSrc":"brief:0","by":{"0":"9","1":"passim","2":"passim","3":"10, 20, 23"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"26","2":"passim"}},{"t":"usc","label":"35 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/35/301","by":{"0":"20, 20, 22"}},{"t":"usc","label":"35 U.S.C. § 302","url":"https://www.law.cornell.edu/uscode/text/35/302","stext":{"head":"§302. Request for reexamination","paras":[[0,"Any person at any time may file a request for reexamination by the Office of any claim of a patent on the basis of any prior art cited under the provisions of section 301. The request must be in writing and must be accompanied by payment of a reexamination fee established by the Director pursuant to the provisions of section 41. The request must set forth the pertinency and manner of applying cited prior art to every claim for which reexamination is requested. Unless the requesting person is the owner of the patent, the Director promptly will send a copy of the request to the owner of record of the patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/302?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§302. Request for reexamination","tname":"Patents","by":{"0":"20"}},{"t":"usc","label":"35 U.S.C. § 303","url":"https://www.law.cornell.edu/uscode/text/35/303","subs":["(a)","(c)"],"stext":{"head":"§303. Determination of issue by Director","paras":[[0,"(a) Within three months following the filing of a request for reexamination under the provisions of section 302, the Director will determine whether a substantial new question of patentability affecting any claim of the patent concerned is raised by the request, with or without consideration of other patents or printed publications. On his own initiative, and any time, the Director may determine whether a substantial new question of patentability is raised by patents and publications discovered by him or cited under the provisions of section 301 or 302. The existence of a substantial new question of patentability is not precluded by the fact that a patent or printed publication was previously cited by or to the Office or considered by the Office."],[0,"(b) A record of the Director's determination under subsection (a) of this section will be placed in the official file of the patent, and a copy promptly will be given or mailed to the owner of record of the patent and to the person requesting reexamination, if any."],[0,"(c) A determination by the Director pursuant to subsection (a) of this section that no substantial new question of patentability has been raised will be final and nonappealable. Upon such a determination, the Director may refund a portion of the reexamination fee required under section 302."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/303?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§303. Determination of issue by Director","tname":"Patents","by":{"0":"2, 2, 18, 18, 18","1":"21, 21, 22","2":"37, passim","3":"14, 1, 12"}},{"t":"usc","label":"35 U.S.C. § 304","url":"https://www.law.cornell.edu/uscode/text/35/304","by":{"0":"2"}},{"t":"usc","label":"35 U.S.C. § 305","url":"https://www.law.cornell.edu/uscode/text/35/305","by":{"0":"2"}},{"t":"usc","label":"35 U.S.C. § 306","url":"https://www.law.cornell.edu/uscode/text/35/306","by":{"0":"2, 18"}},{"t":"usc","label":"35 U.S.C. § 311","url":"https://www.law.cornell.edu/uscode/text/35/311","subs":["(2000)","(a)","(b)","(c)"],"stext":{"head":"§311. Inter partes review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute an inter partes review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the review."],[0,"(b) Scope.—A petitioner in an inter partes review may request to cancel as unpatentable 1 or more claims of a patent only on a ground that could be raised under section 102 or 103 and only on the basis of prior art consisting of patents or printed publications."],[0,"(c) Filing Deadline.—A petition for inter partes review shall be filed after the later of either—"],[1,"(1) the date that is 9 months after the grant of a patent; or"],[1,"(2) if a post-grant review is instituted under chapter 32, the date of the termination of such post-grant review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/311?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":1,"head":"§311. Inter partes review","tname":"Patents","by":{"0":"21, 2, 2, 12, 13, 25, 12, 13, 25, 12, 13, 25, 12, 13, 25","1":"18, 4, 23, 5","2":"passim, 21","3":"13, 1, 3, 9, 19"}},{"t":"usc","label":"35 U.S.C. § 312","url":"https://www.law.cornell.edu/uscode/text/35/312","subs":["(a)","(c)","(a)(1)","(a)(2)","(a)(3)","(a)(5)","(2010)","(c)(2010)","(c)(2000)","(c)(3)"],"stext":{"head":"§312. Petitions","paras":[[0,"(a) Requirements of Petition.—A petition filed under section 311 may be considered only if—"],[1,"(1) the petition is accompanied by payment of the fee established by the Director under section 311;"],[1,"(2) the petition identifies all real parties in interest;"],[1,"(3) the petition identifies, in writing and with particularity, each claim challenged, the grounds on which the challenge to each claim is based, and the evidence that supports the grounds for the challenge to each claim, including—"],[2,"(A) copies of patents and printed publications that the petitioner relies upon in support of the petition; and"],[2,"(B) affidavits or declarations of supporting evidence and opinions, if the petitioner relies on expert opinions;"],[1,"(4) the petition provides such other information as the Director may require by regulation; and"],[1,"(5) the petitioner provides copies of any of the documents required under paragraphs (2), (3), and (4) to the patent owner or, if applicable, the designated representative of the patent owner."],[0,"(b) Public Availability.—As soon as practicable after the receipt of a petition under section 311, the Director shall make the petition available to the public."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/312?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":4,"head":"§312. Petitions","tname":"Patents","by":{"0":"2, 2, 12, 13, 25, 12, 13, 25, 12, 13, 25, 12, 13, 25, 12, 13, 25","1":"2, 22, 22, 5, 5, 4, 25, 26, 33, 22","2":"passim, 18, 35","3":"6, 8, 14, 14, 1, 3, 9, 19, 3, 8, 1, 12, 13, 15"}},{"t":"usc","label":"35 U.S.C. § 313","url":"https://www.law.cornell.edu/uscode/text/35/313","stext":{"head":"§313. Preliminary response to petition","paras":[[0,"If an inter partes review petition is filed under section 311, the patent owner shall have the right to file a preliminary response to the petition, within a time period set by the Director, that sets forth reasons why no inter partes review should be instituted based upon the failure of the petition to meet any requirement of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/313?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":1,"head":"§313. Preliminary response to petition","tname":"Patents","by":{"0":"2, 3","1":"5, 8, 13, 18, 31","2":"14, 20, 44","3":"6"}},{"t":"usc","label":"35 U.S.C. § 314","url":"https://www.law.cornell.edu/uscode/text/35/314","subs":["(a)","(b)(3)","(b)","(b)(2)","(d)"],"stext":{"head":"§314. Institution of inter partes review","paras":[[0,"(a) Threshold.—The Director may not authorize an inter partes review to be instituted unless the Director determines that the information presented in the petition filed under section 311 and any response filed under section 313 shows that there is a reasonable likelihood that the petitioner would prevail with respect to at least 1 of the claims challenged in the petition."],[0,"(b) Timing.—The Director shall determine whether to institute an inter partes review under this chapter pursuant to a petition filed under section 311 within 3 months after—"],[1,"(1) receiving a preliminary response to the petition under section 313; or"],[1,"(2) if no such preliminary response is filed, the last date on which such response may be filed."],[0,"(c) Notice.—The Director shall notify the petitioner and patent owner, in writing, of the Director's determination under subsection (a), and shall make such notice available to the public as soon as is practicable. Such notice shall include the date on which the review shall commence."],[0,"(d) No Appeal.—The determination by the Director whether to institute an inter partes review under this section shall be final and nonappealable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/314?type=usc&year=mostrecent&link-type=html"},"op":19,"ar":6,"head":"§314. Institution of inter partes review","tname":"Patents","by":{"0":"2, 2, 3, 3, 3, 3, 3","1":"6, 16, 18, 22, 32, 33, passim, 6, passim","2":"passim, passim, passim","3":"passim, passim, 6, 9, 10, 18, passim"}},{"t":"usc","label":"35 U.S.C. § 317","url":"https://www.law.cornell.edu/uscode/text/35/317","subs":["(a)"],"stext":{"head":"§317. Settlement","paras":[[0,"(a) In General.—An inter partes review instituted under this chapter shall be terminated with respect to any petitioner upon the joint request of the petitioner and the patent owner, unless the Office has decided the merits of the proceeding before the request for termination is filed. If the inter partes review is terminated with respect to a petitioner under this section, no estoppel under section 315(e) shall attach to the petitioner, or to the real party in interest or privy of the petitioner, on the basis of that petitioner's institution of that inter partes review. If no petitioner remains in the inter partes review, the Office may terminate the review or proceed to a final written decision under section 318(a)."],[0,"(b) Agreements in Writing.—Any agreement or understanding between the patent owner and a petitioner, including any collateral agreements referred to in such agreement or understanding, made in connection with, or in contemplation of, the termination of an inter partes review under this section shall be in writing and a true copy of such agreement or understanding shall be filed in the Office before the termination of the inter partes review as between the parties. At the request of a party to the proceeding, the agreement or understanding shall be treated as business confidential information, shall be kept separate from the file of the involved patents, and shall be made available only to Federal Government agencies on written request, or to any person on a showing of good cause."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/317?type=usc&year=mostrecent&link-type=html"},"head":"§317. Settlement","tname":"Patents","by":{"0":"2","1":"24, 40"}},{"t":"usc","label":"35 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/35/1","stext":{"head":"§1. Establishment","paras":[[0,"(a) Establishment.—The United States Patent and Trademark Office is established as an agency of the United States, within the Department of Commerce. In carrying out its functions, the United States Patent and Trademark Office shall be subject to the policy direction of the Secretary of Commerce, but otherwise shall retain responsibility for decisions regarding the management and administration of its operations and shall exercise independent control of its budget allocations and expenditures, personnel decisions and processes, procurements, and other administrative and management functions in accordance with this title and applicable provisions of law. Those operations designed to grant and issue patents and those operations which are designed to facilitate the registration of trademarks shall be treated as separate operating units within the Office."],[0,"(b) Offices.—The United States Patent and Trademark Office shall maintain its principal office in the metropolitan Washington, D.C., area, for the service of process and papers and for the purpose of carrying out its functions. The United States Patent and Trademark Office shall be deemed, for purposes of venue in civil actions, to be a resident of the district in which its principal office is located, except where jurisdiction is otherwise provided by law. The United States Patent and Trademark Office may establish satellite offices in such other places in the United States as it considers necessary and appropriate in the conduct of its business."],[0,"(c) Reference.—For purposes of this title, the United States Patent and Trademark Office shall also be referred to as the \"Office\" and the \"Patent and Trademark Office\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/1?type=usc&year=mostrecent&link-type=html"},"head":"§1. Establishment","tname":"Patents","by":{"0":"2","2":"passim"}},{"t":"usc","label":"35 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/35/102","by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/35/103","by":{"0":"3"}},{"t":"usc","label":"35 U.S.C. § 131","url":"https://www.law.cornell.edu/uscode/text/35/131","by":{"0":"2"}},{"t":"usc","label":"35 U.S.C. § 141","url":"https://www.law.cornell.edu/uscode/text/35/141","subs":["(b)","(c)"],"stext":{"head":"§141. Appeal to Court of Appeals for the Federal Circuit","paras":[[0,"(a) Examinations.—An applicant who is dissatisfied with the final decision in an appeal to the Patent Trial and Appeal Board under section 134(a) may appeal the Board's decision to the United States Court of Appeals for the Federal Circuit. By filing such an appeal, the applicant waives his or her right to proceed under section 145."],[0,"(b) Reexaminations.—A patent owner who is dissatisfied with the final decision in an appeal of a reexamination to the Patent Trial and Appeal Board under section 134(b) may appeal the Board's decision only to the United States Court of Appeals for the Federal Circuit."],[0,"(c) Post-Grant and Inter Partes Reviews.—A party to an inter partes review or a post-grant review who is dissatisfied with the final written decision of the Patent Trial and Appeal Board under section 318(a) or 328(a) (as the case may be) may appeal the Board's decision only to the United States Court of Appeals for the Federal Circuit."],[0,"(d) Derivation Proceedings.—A party to a derivation proceeding who is dissatisfied with the final decision of the Patent Trial and Appeal Board in the proceeding may appeal the decision to the United States Court of Appeals for the Federal Circuit, but such appeal shall be dismissed if any adverse party to such derivation proceeding, within 20 days after the appellant has filed notice of appeal in accordance with section 142, files notice with the Director that the party elects to have all further proceedings conducted as provided in section 146. If the appellant does not, within 30 days after the filing of such notice by the adverse party, file a civil action under section 146, the Board's decision shall govern the further proceedings in the case."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/141?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§141. Appeal to Court of Appeals for the Federal Circuit","tname":"Patents","by":{"0":"8, 8","1":"2, 7, 18"}},{"t":"usc","label":"35 U.S.C. § 143","url":"https://www.law.cornell.edu/uscode/text/35/143","by":{"0":"8"}},{"t":"usc","label":"35 U.S.C. § 144","url":"https://www.law.cornell.edu/uscode/text/35/144","by":{"0":"18"}},{"t":"usc","label":"35 U.S.C. § 315","url":"https://www.law.cornell.edu/uscode/text/35/315","subs":["(a)(1)","(a)(2)","(b)","(c)","(e)(1)","(a)","(e)(2)"],"stext":{"head":"§315. Relation to other proceedings or actions","paras":[[0,"(a) Infringer's Civil Action.—"],[1,"(1) Inter partes review barred by civil action.—An inter partes review may not be instituted if, before the date on which the petition for such a review is filed, the petitioner or real party in interest filed a civil action challenging the validity of a claim of the patent."],[1,"(2) Stay of civil action.—If the petitioner or real party in interest files a civil action challenging the validity of a claim of the patent on or after the date on which the petitioner files a petition for inter partes review of the patent, that civil action shall be automatically stayed until either—"],[2,"(A) the patent owner moves the court to lift the stay;"],[2,"(B) the patent owner files a civil action or counterclaim alleging that the petitioner or real party in interest has infringed the patent; or"],[2,"(C) the petitioner or real party in interest moves the court to dismiss the civil action."],[1,"(3) Treatment of counterclaim.—A counterclaim challenging the validity of a claim of a patent does not constitute a civil action challenging the validity of a claim of a patent for purposes of this subsection."],[0,"(b) Patent Owner's Action.—An inter partes review may not be instituted if the petition requesting the proceeding is filed more than 1 year after the date on which the petitioner, real party in interest, or privy of the petitioner is served with a complaint alleging infringement of the patent. The time limitation set forth in the preceding sentence shall not apply to a request for joinder under subsection (c)."],[0,"(c) Joinder.—If the Director institutes an inter partes review, the Director, in his or her discretion, may join as a party to that inter partes review any person who properly files a petition under section 311 that the Director, after receiving a preliminary response under section 313 or the expiration of the time for filing such a response, determines warrants the institution of an inter partes review under section 314."],[0,"(d) Multiple Proceedings.—Notwithstanding sections 135(a), 251, and 252, and chapter 30, during the pendency of an inter partes review, if another proceeding or matter involving the patent is before the Office, the Director may determine the manner in which the inter partes review or other proceeding or matter may proceed, including providing for stay, transfer, consolidation, or termination of any such matter or proceeding."],[0,"(e) Estoppel.—"],[1,"(1) Proceedings before the office.—The petitioner in an inter partes review of a claim in a patent under this chapter that results in a final written decision under section 318(a), or the real party in interest or privy of the petitioner, may not request or maintain a proceeding before the Office with respect to that claim on any ground that the petitioner raised or reasonably could have raised during that inter partes review."],[1,"(2) Civil actions and other proceedings.—The petitioner in an inter partes review of a claim in a patent under this chapter that results in a final written decision under section 318(a), or the real party in interest or privy of the petitioner, may not assert either in a civil action arising in whole or in part under section 1338 of title 28 or in a proceeding before the International Trade Commission under section 337 of the Tariff Act of 1930 that the claim is invalid on any ground that the petitioner raised or reasonably could have raised during that inter partes review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/315?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§315. Relation to other proceedings or actions","tname":"Patents","by":{"0":"3, 3, 3, 3, 3, 3, 3, 3","1":"4, 5, 40, passim, 23, 40","2":"20, 21, passim, 38","3":"1, 3, 9, 19, passim"}},{"t":"usc","label":"35 U.S.C. § 316","url":"https://www.law.cornell.edu/uscode/text/35/316","subs":["(a)","(a)(2)","(a)(4)","(a)(5)","(a)(8)","(a)(10)","(a)(13)","(a)(11)","(d)","(d)(1)","(e)"],"stext":{"head":"§316. Conduct of inter partes review","paras":[[0,"(a) Regulations.—The Director shall prescribe regulations—"],[1,"(1) providing that the file of any proceeding under this chapter shall be made available to the public, except that any petition or document filed with the intent that it be sealed shall, if accompanied by a motion to seal, be treated as sealed pending the outcome of the ruling on the motion;"],[1,"(2) setting forth the standards for the showing of sufficient grounds to institute a review under section 314(a);"],[1,"(3) establishing procedures for the submission of supplemental information after the petition is filed;"],[1,"(4) establishing and governing inter partes review under this chapter and the relationship of such review to other proceedings under this title;"],[1,"(5) setting forth standards and procedures for discovery of relevant evidence, including that such discovery shall be limited to—"],[2,"(A) the deposition of witnesses submitting affidavits or declarations; and"],[2,"(B) what is otherwise necessary in the interest of justice;"],[1,"(6) prescribing sanctions for abuse of discovery, abuse of process, or any other improper use of the proceeding, such as to harass or to cause unnecessary delay or an unnecessary increase in the cost of the proceeding;"],[1,"(7) providing for protective orders governing the exchange and submission of confidential information;"],[1,"(8) providing for the filing by the patent owner of a response to the petition under section 313 after an inter partes review has been instituted, and requiring that the patent owner file with such response, through affidavits or declarations, any additional factual evidence and expert opinions on which the patent owner relies in support of the response;"],[1,"(9) setting forth standards and procedures for allowing the patent owner to move to amend the patent under subsection (d) to cancel a challenged claim or propose a reasonable number of substitute claims, and ensuring that any information submitted by the patent owner in support of any amendment entered under subsection (d) is made available to the public as part of the prosecution history of the patent;"],[1,"(10) providing either party with the right to an oral hearing as part of the proceeding;"],[1,"(11) requiring that the final determination in an inter partes review be issued not later than 1 year after the date on which the Director notices the institution of a review under this chapter, except that the Director may, for good cause shown, extend the 1-year period by not more than 6 months, and may adjust the time periods in this paragraph in the case of joinder under section 315(c);"],[1,"(12) setting a time period for requesting joinder under section 315(c); and"],[1,"(13) providing the petitioner with at least 1 opportunity to file written comments within a time period established by the Director."],[0,"(b) Considerations.—In prescribing regulations under this section, the Director shall consider the effect of any such regulation on the economy, the integrity of the patent system, the efficient administration of the Office, and the ability of the Office to timely complete proceedings instituted under this chapter."],[0,"(c) Patent Trial and Appeal Board.—The Patent Trial and Appeal Board shall, in accordance with section 6, conduct each inter partes review instituted under this chapter."],[0,"(d) Amendment of the Patent.—"],[1,"(1) In general.—During an inter partes review instituted under this chapter, the patent owner may file 1 motion to amend the patent in 1 or more of the following ways:"],[2,"(A) Cancel any challenged patent claim."],[2,"(B) For each challenged claim, propose a reasonable number of substitute claims."],[1,"(2) Additional motions.—Additional motions to amend may be permitted upon the joint request of the petitioner and the patent owner to materially advance the settlement of a proceeding under section 317, or as permitted by regulations prescribed by the Director."],[1,"(3) Scope of claims.—An amendment under this subsection may not enlarge the scope of the claims of the patent or introduce new matter."],[0,"(e) Evidentiary Standards.—In an inter partes review instituted under this chapter, the petitioner shall have the burden of proving a proposition of unpatentability by a preponderance of the evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/316?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§316. Conduct of inter partes review","tname":"Patents","by":{"0":"3, 3, 3, 3, 3, 3, 3, 3","1":"6, 7, 36, 19","2":"23, 15, 15"}},{"t":"usc","label":"35 U.S.C. § 318","url":"https://www.law.cornell.edu/uscode/text/35/318","subs":["(a)"],"stext":{"head":"§318. Decision of the Board","paras":[[0,"(a) Final Written Decision.—If an inter partes review is instituted and not dismissed under this chapter, the Patent Trial and Appeal Board shall issue a final written decision with respect to the patentability of any patent claim challenged by the petitioner and any new claim added under section 316(d)."],[0,"(b) Certificate.—If the Patent Trial and Appeal Board issues a final written decision under subsection (a) and the time for appeal has expired or any appeal has terminated, the Director shall issue and publish a certificate canceling any claim of the patent finally determined to be unpatentable, confirming any claim of the patent determined to be patentable, and incorporating in the patent by operation of the certificate any new or amended claim determined to be patentable."],[0,"(c) Intervening Rights.—Any proposed amended or new claim determined to be patentable and incorporated into a patent following an inter partes review under this chapter shall have the same effect as that specified in section 252 for reissued patents on the right of any person who made, purchased, or used within the United States, or imported into the United States, anything patented by such proposed amended or new claim, or who made substantial preparation therefor, before the issuance of a certificate under subsection (b)."],[0,"(d) Data on Length of Review.—The Office shall make available to the public data describing the length of time between the institution of, and the issuance of a final written decision under subsection (a) for, each inter partes review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/318?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§318. Decision of the Board","tname":"Patents","by":{"0":"3","1":"7, 14, 19, 29, 30, 40","2":"passim","3":"17, 19"}},{"t":"usc","label":"35 U.S.C. § 319","url":"https://www.law.cornell.edu/uscode/text/35/319","stext":{"head":"§319. Appeal","paras":[[0,"A party dissatisfied with the final written decision of the Patent Trial and Appeal Board under section 318(a) may appeal the decision pursuant to sections 141 through 144. Any party to the inter partes review shall have the right to be a party to the appeal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/319?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§319. Appeal","tname":"Patents","by":{"0":"3","1":"7, 18","2":"passim","3":"16, 17"}},{"t":"usc","label":"35 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/35/321","subs":["(b)"],"by":{"0":"3, 3"}},{"t":"usc","label":"35 U.S.C. § 324","url":"https://www.law.cornell.edu/uscode/text/35/324","subs":["(e)(1)"],"by":{"0":"13, 24"}},{"t":"law","label":"21st Century Department of Justice Appropriations Authorization Act, Pub. L. No. 107-273","url":"https://www.govinfo.gov/link/plaw/107/public/273","by":{"0":"23"}},{"t":"reg","label":"37 C.F.R. pt. 42","url":"https://www.ecfr.gov/current/title-37/part-42","by":{"0":"6","2":"2, 4, 19, 25"}},{"t":"case","label":"Amneal Pharm., LLC v. Endo Pharm. Inc.","cite":"2018 WL 446628","y":2018,"court":"PTAB Jan. 10","by":{"1":"38"}},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":2,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","2":"passim","3":"2"}},{"t":"case","label":"Bowtech, Inc. v. MCP IP, LLC","cite":"2019 WL 2894443","y":2019,"court":"PTAB July 3","by":{"1":"38"}},{"t":"case","label":"Brewster v. Gage","cite":"280 U.S. 327","y":1930,"id":"scdb/1929-109","sc":1,"sum":"1. Under the Revenue Acts of 1918 and 1921, which provide,, §§ 202 (a), that for the purpose of ascertaining the gain. derived or loss sustained from the sale of property \"acquired\" on or after March Argument for Petitioner. 1, 1913, the basis shall be its cost, the latter Act declaring also that in case of \"property acquired by bequest, devise, or inheritance, the basis shall be the fair market price or value of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Briscoe v. Bell","cite":"432 U.S. 404","y":1977,"id":"1976/76-60","sc":1,"sum":"The provision of § 4 (b) of the Voting Rights Act of 1965 that a determination of the Attorney General or Director of the Census that a State is covered by the Act \"shall not be reviewable in any court\" held absolutely to preclude judicial review of such a determination. Hence the District Court and Court of Appeals erred in holding that they had jurisdiction to review petitioners' claims that the Attorney General …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 20","3":"5, 14, 15"}},{"t":"case","label":"Briscoe v. Levi","cite":"535 F.2d 1259","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/535/1259/","by":{"1":"20"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Crawford v. Burke","cite":"195 U.S. 176","y":1904,"id":"scdb/1904-044","sc":1,"sum":"A plea puis darrien continuance waives all prior pleas and amounts to an admission of the plaintiff’s cause of action.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20","3":"13"}},{"t":"case","label":"Cree, Inc. v. Document Security Sys., Inc.","cite":"2018 WL 6016827","y":2018,"court":"PTAB Nov. 16","by":{"1":"38"}},{"t":"case","label":"Deeper, UAB v. Vexilar, Inc.","cite":"2019 WL 328753","y":2019,"court":"PTAB Jan. 24","by":{"1":"6"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"1":"21"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"FLIR Sys., Inc. v. Garmin Corp.","cite":"2018 WL 5276319","y":2018,"court":"PTAB Oct. 22","by":{"1":"38"}},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"sum":"The Court found that the rights given by the Geneva Convention to prisoners of war could be enforced by federal court.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Harmonic Inc. v. Avid Tech., Inc.","cite":"815 F.3d 1356","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/815/1356/","by":{"1":"6","3":"17"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"op":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"17, 20, 22","2":"14"}},{"t":"case","label":"HTC Corp. v. AGIS Software Dev., LLC","cite":"2019 WL 2866034","y":2019,"court":"PTAB July 2","by":{"1":"23"}},{"t":"case","label":"Infiltrator Water Techs., LLC v. Presby Patent Trust","cite":"2018 WL 4773425","y":2018,"court":"PTAB Oct. 1","by":{"1":"38"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Intel Corp. v. Alacritech, Inc.","cite":"2018 WL 2735469","y":2018,"court":"PTAB June 5","by":{"1":"38"}},{"t":"case","label":"Intel Corp. v. Alacritech, Inc.","cite":"2018 WL 2740385","y":2018,"court":"PTAB June 5","by":{"1":"38"}},{"t":"case","label":"Lamie v. U.S. Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Lear, Inc. v. Adkins","cite":"395 U.S. 653","y":1969,"id":"1968/56","sc":1,"sum":"Respondent, an engineer and inventor, was hired in 1952 by petitioner (Lear) to help solve gyroscope development problems. They had agreed that- \"new ideas, discoveries, inventions etc. related to... vertical gyros become the property of\" respondent, and that the inventor would grant Lear a license as to all ideas he might develop \"on a mutually satisfactory royalty basis.\" Shortly thereafter respondent developed a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Merck Sharp & Dohme Corp. v. GlaxoSmithKine Biologicals SA","cite":"2018 WL 6707892","y":2018,"court":"PTAB Dec. 18","by":{"1":"38"}},{"t":"case","label":"Mobile Tech, Inc. v. Sennco Sols., Inc.","cite":"2018 WL 1891466","y":2018,"court":"PTAB Apr. 10","by":{"1":"38"}},{"t":"case","label":"Oil States Energy Servs., LLC v. Greene’s Energy Grp., LLC","cite":"138 S. Ct. 1365","y":2018,"id":"2017/16-712","sc":1,"op":4,"sum":"The Court decided that inter partes review, which authorizes the United States Patent and Trademark Office to reconsider and cancel an already-issued patent claim under 35 U.S.C. §§ 311-391, does not violate Article III or the Seventh Amendment of the Constitution.","sumSrc":"Oyez","by":{"1":"4, 6, 36","2":"42","3":"12"}},{"t":"case","label":"Pirie v. Chi. Title & Tr. Co.","cite":"182 U.S. 438","y":1901,"id":"scdb/1900-068","sc":1,"sum":"Frank Brothers were adjudged bankrupts in February, 1899. For a long time prior to that Pirie & Co. had dealt with them, selling them merchandise. Within four months prior to the adjudication of bankruptcy Pirie & Co. received from them $1336.79, leaving a balance still due and unpaid of $3093.98. When this payment was made Frank Brothers were hopelessly insolvent to the knowledge of Frank Brothers, but Pirie & Co. …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Pope Mfg. Co. v. Gormully","cite":"144 U.S. 224","y":1892,"id":"scdb/1891-167","sc":1,"sum":"A court of equity will not enforce the specific performance of a contract wherein the defendant, in consideration of receiving a license to use certain patents belonging to the plaintiff during the life of such patents, agrees never to import, manufacture or sell any machines or devices covered by certain other patents, unless permitted in writing so to do, nor to dispute or contest the validity of such patents or …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Power Integrations, Inc. v. Semiconductor Components Indus., LLC","cite":"926 F.3d 1306","y":2019,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/926/1306/","by":{"1":"18, 27, 39","3":"23"}},{"t":"case","label":"Precision Instrument Mfg. Co. v. Auto. Maint. Mach. Co.","cite":"324 U.S. 806","y":1945,"id":"scdb/1944-152","sc":1,"by":{"1":"35, 37"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21","3":"13"}},{"t":"case","label":"Semiconductor Components Indus., LLC v. Power Integrations, Inc.","cite":"2018 WL 813000","y":2018,"court":"PTAB Feb. 8","by":{"1":"38"}},{"t":"case","label":"Unified Patents Inc. v. Bradium Techs. LLC","cite":"2018 WL 6721788","y":2018,"court":"PTAB Dec. 20","by":{"1":"38"}},{"t":"case","label":"Unified Patents, Inc. v. Realtime Adaptive Streaming, LLC","cite":"2018 WL 6504233","y":2018,"court":"PTAB Oct. 11","by":{"1":"38"}},{"t":"case","label":"United States v. Erika, Inc.","cite":"456 U.S. 201","y":1982,"id":"1981/80-1594","sc":1,"sum":"The Court of Claims has no jurisdiction to review determinations by private insurance carriers of the amount of benefits payable under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"VirnetX Inc. v. Mangrove Partners Master Fund, Ltd.","cite":"2019 WL 2912776","y":2019,"court":"Fed. Cir. July 8","by":{"1":"23"}},{"t":"case","label":"Watson Labs., Inc. v. United Therapeutics Corp.","cite":"2018 WL 396243","y":2018,"court":"PTAB Jan. 11","by":{"1":"38"}},{"t":"case","label":"Wi-Fi One, LLC v. Broadcom Corp.","cite":"837 F.3d 1329","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/837/1329/","by":{"1":"10"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"20, 22, 35"}},{"t":"case","label":"Worlds Inc. v. Bungie, Inc.","cite":"903 F.3d 1237","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/903/1237/","by":{"1":"39","3":"23"}},{"t":"reg","label":"37 C.F.R. § 42.100","url":"https://www.ecfr.gov/current/title-37/section-42.100","by":{"1":"6"}},{"t":"reg","label":"37 C.F.R. § 42.108","url":"https://www.ecfr.gov/current/title-37/section-42.108","subs":["(a)","(c)"],"by":{"1":"4, 29","2":"19"}},{"t":"reg","label":"37 C.F.R. § 42.4","url":"https://www.ecfr.gov/current/title-37/section-42.4","subs":["(a)"],"by":{"1":"4"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"1":"2, 3","2":"passim"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"1":"16","2":"passim, 13, 16, 27","3":"4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"usc","label":"35 U.S.C. § 325","url":"https://www.law.cornell.edu/uscode/text/35/325","subs":["(d)"],"by":{"1":"40"}},{"t":"reg","label":"Office Patent Trial Practice Guide, 77 Fed. Reg. 48756,","url":"https://www.govinfo.gov/link/fr/77/48756","by":{"1":"5"}},{"t":"case","label":"Arista Networks, Inc. v. Cisco Sys., Inc.","cite":"908 F.3d 792","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/908/792/","sum":"Holding that the doctrine of “assignor estoppel has no place in IPR proceedings”.","sumSrc":"brief:2","by":{"2":"22"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"op":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"135 S. Ct. 1124","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"2":"28, 29, 30"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"23, 24"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"136 S. Ct. 1562","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"2":"28, 30"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"134 S. Ct. 1749","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Ortiz v. Jordan","cite":"562 U.S. 180","y":2011,"id":"2010/09-737","sc":1,"sum":"The Court held that a party may not appeal a denial of summary judgement after a district court has conducted a full trial on the merits.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Regents of the Univ. of Minnesota v. LSI Corp.","cite":"926 F.3d 1327","y":2019,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/926/1327/","sum":"Holding “that state sovereign immunity does not apply to IPR proceedings”.","sumSrc":"brief:2","by":{"2":"23"}},{"t":"case","label":"Roberts v. Sea-Land Servs.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15","3":"11"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Saint Regis Mohawk Tribe v. Mylan Pharm. Inc.","cite":"896 F.3d 1322","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/896/1322/","ar":1,"by":{"2":"22"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"sum":"The Court held that the district court has maritime jurisdiction when the incident in question represents a potential hazard to maritime commerce and bears a substantial relationship to maritime activity.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"2, 11"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns, Inc.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"2":"13"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","stext":{"head":"§704. Actions reviewable","paras":[[0,"Agency action made reviewable by statute and final agency action for which there is no other adequate remedy in a court are subject to judicial review. A preliminary, procedural, or intermediate agency action or ruling not directly reviewable is subject to review on the review of the final agency action. Except as otherwise expressly required by statute, agency action otherwise final is final for the purposes of this section whether or not there has been presented or determined an application for a declaratory order, for any form of reconsideration, or, unless the agency otherwise requires by rule and provides that the action meanwhile is inoperative, for an appeal to superior agency authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/704?type=usc&year=mostrecent&link-type=html"},"head":"§704. Actions reviewable","tname":"Government Organization and Employees","by":{"2":"7, 13, 25, 27","3":"16"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)","(2)(C)"],"by":{"2":"passim, passim, passim"}},{"t":"usc","label":"35 U.S.C. § 112","url":"https://www.law.cornell.edu/uscode/text/35/112","by":{"2":"25, 30"}},{"t":"usc","label":"35 U.S.C. § 285","url":"https://www.law.cornell.edu/uscode/text/35/285","by":{"2":"38"}},{"t":"reg","label":"37 C.F.R. § 42.104","url":"https://www.ecfr.gov/current/title-37/section-42.104","subs":["(a)","(b)"],"by":{"2":"4, 4"}},{"t":"reg","label":"37 C.F.R. § 42.2","url":"https://www.ecfr.gov/current/title-37/section-42.2","by":{"2":"25"}},{"t":"reg","label":"37 C.F.R. § 42.3","url":"https://www.ecfr.gov/current/title-37/section-42.3","subs":["(b)"],"by":{"2":"19"}},{"t":"reg","label":"37 C.F.R. § 42.73","url":"https://www.ecfr.gov/current/title-37/section-42.73","subs":["(a)"],"by":{"2":"25","3":"16"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Consol. Edison Co. of N.Y. v. NLRB","cite":"305 U.S. 197","y":1938,"id":"scdb/1938-001","sc":1,"sum":"1. The power of the Federal Government, and the provisions of the National Labor Relations Act, extend to the labor relations of public utilities engaged in supplying electrical energy, gas and steam, where the business and activities of the utilities are wholly within a State, and where the quantum of service rendered to customers for strictly intrastate uses is vast and greatly preponderant, but where, …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"case","label":"Garmin Int’l, Inc. v. Cuozzo Speed Techs. LLC","cite":"2013 WL 11311697","y":2013,"court":"PTAB Mar. 5","by":{"3":"22"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"3":"1"}},{"t":"case","label":"PBGC v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Seven-Sky v. Holder","cite":"661 F.3d 1","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/661/1/","by":{"3":"7"}},{"t":"case","label":"Texaco Inc. v. Dagher","cite":"547 U.S. 1","y":2006,"id":"2005/04-805","sc":1,"sum":"The Court ruled that the per se rule against price-fixing should not be applied to price-setting by joint ventures.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"reg","label":"37 C.F.R. § 42.51","url":"https://www.ecfr.gov/current/title-37/section-42.51","subs":["(b)(1)","(b)(2)"],"by":{"3":"22, 22"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(b)(1)"],"by":{"3":"22"}}]};